    lane_lease_digest: ?[]const u8 = null,
    revision: []const u8 = "HEAD",
    revision_set: bool = false,
    format: OutputFormat = .json,

    fn deinit(self: *Args, allocator: std.mem.Allocator) void {
        self.materialization_receipt_paths.deinit(allocator);
    }
};

const EventKind = enum {
    campaign_created,
    target_bundle_admitted,
    scenario_admitted,
    attempt_recorded,
    grade_recorded,
    feedback_recorded,
    change_recorded,
    publication_recorded,
    failure_signature_recorded,
    hypothesis_recorded,
    experiment_recorded,
    next_step_recorded,
    campaign_closed,
    trial_registered,
    lane_started,
    lane_finished,
    grade_committed,
    pair_grade_committed,
    pair_grade_recorded,
    trial_revealed,
    trial_closed,

    fn parse(raw: []const u8) ?EventKind {
        inline for (@typeInfo(EventKind).@"enum".fields) |field| {
            if (std.mem.eql(u8, raw, field.name)) return @enumFromInt(field.value);
        }
        return null;
    }

    fn name(self: EventKind) []const u8 {
        return @tagName(self);
    }
};

