    visible_input_fingerprint: []u8,
    hidden_reference_fingerprint: ?[]u8,
    source_profile_fingerprint: ?[]u8,
    environment_fingerprint: []u8,
    effect_policy_json: []u8,
    effect_policy_fingerprint: []u8,
    replay_policy_fingerprint: []u8,
