fn testReplaceFirstCurrent(
    allocator: std.mem.Allocator,
    current: *[]u8,
    needle: []const u8,
    replacement: []const u8,
) !void {
    const next = try testReplaceFirstAlloc(allocator, current.*, needle, replacement);
    allocator.free(current.*);
