    try tmp.dir.symLink(std.testing.io, "real-proof-dir", "proof-link-dir", .{ .is_directory = true });
    const parent_link_path = try std.fs.path.join(std.testing.allocator, &.{ repo, "proof-link-dir", "proof.tar" });
