    try retrace_core.hctp_trial_custody.validateArmMapNonce(compiled_nonces[0]);
    for (compiled_nonces[1..]) |compiled_nonce| {
        try retrace_core.hctp_trial_custody.validateNonce(compiled_nonce);
    }
