    var reveal_argv: std.ArrayList([]const u8) = .empty;
    defer reveal_argv.deinit(allocator);
    try reveal_argv.appendSlice(allocator, &.{
        hylo_operator_recipe_paths.ledger_path,
        "--source",
        "hylo",
        "reveal-trial",
        "--repo",
